from datetime import date, timedelta
from typing import Dict, Set


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books: Set[str] = set()
        # book_id -> (user, borrow_date)
        self.borrowed_books: Dict[str, tuple[str, date]] = {}
        # user -> set of book_ids currently borrowed
        self.user_borrowed: Dict[str, Set[str]] = {}
        # user -> total unpaid fines
        self.fines: Dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book '{book_id}' does not exist in the library.")
        if book_id in self.borrowed_books:
            raise ValueError(f"Book '{book_id}' is already borrowed.")

        user_books = self.user_borrowed.get(user, set())
        has_fines = self.unpaid_fines(user) > 0.0

        if has_fines and len(user_books) >= 1:
            raise ValueError(f"User '{user}' has unpaid fines and can only borrow at most one book at a time.")

        self.borrowed_books[book_id] = (user, day)
        self.user_borrowed.setdefault(user, set()).add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        if book_id not in self.borrowed_books or self.borrowed_books[book_id][0] != user:
            raise ValueError(f"User '{user}' has not borrowed book '{book_id}'.")

        _, borrow_day = self.borrowed_books.pop(book_id)
        self.user_borrowed[user].remove(book_id)
        if not self.user_borrowed[user]:
            del self.user_borrowed[user]

        due_date = borrow_day + timedelta(days=self.loan_days)
        delay = (day - due_date).days
        fine = max(0, delay) * self.daily_fine

        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return float(fine)

    def unpaid_fines(self, user: str) -> float:
        return float(self.fines.get(user, 0.0))

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0
```

